package com.luminor.tavernquest.feature.settings
import androidx.lifecycle.*;import com.luminor.tavernquest.domain.repository.SettingsRepository;import com.luminor.tavernquest.domain.usecase.settings.ResetGameUseCase;import dagger.hilt.android.lifecycle.HiltViewModel;import javax.inject.Inject;import kotlinx.coroutines.flow.*;import kotlinx.coroutines.launch
@HiltViewModel class SettingsViewModel @Inject constructor(private val repo:SettingsRepository,private val reset:ResetGameUseCase):ViewModel(){val ui=repo.observe().map{SettingsUiState(it.soundEnabled,it.hapticsEnabled)}.stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),SettingsUiState());fun sound(v:Boolean){viewModelScope.launch{repo.setSound(v)}};fun haptics(v:Boolean){viewModelScope.launch{repo.setHaptics(v)}};fun reset(){viewModelScope.launch{reset()}}}
